package com.example.app03.domain.entity; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="leads") public class Lead { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(nullable=false) private String status; @Column(nullable=false) private Instant createdAt = Instant.now(); public Long getId(){return id;} public String getName(){return name;} public void setName(String name){this.name=name;} public String getStatus(){return status;} public void setStatus(String status){this.status=status;} public Instant getCreatedAt(){return createdAt;} }
